rows[137507]={title={{9,1931121631},"파열"},description={"^a lightning fissure implodes upon contact with another focused lightning, inflicting ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all players%. this effect leaves targets vulnerable, increasing damage taken from implosion by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","번개의 균열은 집중된 번개와 닿으면 파열되어, 모든 플레이어에게 \0311\031의 자연 피해를 입힙니다.\010\010영향을 받은 대상들은 약해져, 파열로부터 받는 피해가 \0312\031%만큼 증가합니다.",{0,0},{1,2}},aura={"^increases damage taken from implosion by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","파열로 받는 피해 \0311\031%만큼 증가",{0},{1}}}
