rows[137531]={title={{11,2004504971},"파도의 힘"},description={"^protective icy waters encase lu'lin and burst outwards, inflicting ([%+%-]?%d[%d,.%+%-to –]*) frost damage on impact%. while she is channeling this effect, her ranged and spell deflection is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. her dodge chance is increased by ([%+%-]?%d[%d,.%+%-to –]*)%% as well%.$","얼음물로 이루어진 방벽이 루린을 둘러싼 후 바깥쪽으로 터져나가, 충돌 시 \0311\031의 냉기 피해를 입힙니다. 이 주문에 정신을 집중하는 동안에는 루린의 원거리 및 주문 회피가 \0312\031%만큼, 회피율이 \0313\031%만큼 증가합니다.",{0,0,0},{1,2,3}},aura={"^spell deflection increased ([%+%-]?%d[%d,.%+%-to –]*)%%%. ranged deflection increased ([%+%-]?%d[%d,.%+%-to –]*)%%%. dodge chance increased ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주문 회피 \0311\031%만큼 증가\010원거리 회피 \0312\031%만큼 증가\010회피율 \0313\031%만큼 증가",{0,0,0},{1,2,3}}}
