rows[137550]={title={{11,1159453176},"마력의 쇄도"},description={"^upon reaching 90%% health, the mogu regains its power and starts dealing ([%+%-]?%d[%d,.%+%-to –]*)%% more damage and casting ([%+%-]?%d[%d,.%+%-to –]*)%% faster%.$","생명력이 90%가 되면, 모구가 남은 힘을 모조리 끌어올려 \0311\031%의 추가 피해를 입히고 주문 시전이 \0312\031%만큼 빨라집니다.",{0,0},{1,2}},aura={"^dealing ([%+%-]?%d[%d,.%+%-to –]*)%% more damage%. haste increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격력 \0311\031%만큼 증가\010가속 \0312\031%만큼 증가",{0,0},{1,2}}}
rows[137551]={title={{12,1675575993},"삶에 대한 의지"},description={"^the ghostly mogu has a strong desire to return to life%. all healing taken is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","유령 모구는 되살아나고자 하는 강력한 의지를 지니고 있습니다. 받는 치유 효과가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^healing taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. can only be killed if kor'dok is killed%.$","받는 치유 효과 \0311\031%만큼 증가\010코르독이 사망해야만 처치할 수 있음",{0},{1}}}
rows[137552]={title={{13,706531891},"수정 보호막"},description={"^the crystal reacts when struck, encasing the attacker in a shell that absorbs incoming damage and healing%. initially the shell can absorb up to ([%+%-]?%d[%d,.%+%-to –]*)%% of max health in damage, but healing absorbed by the shell is added to this total, up to a cap of ([%+%-]?%d[%d,.%+%-to –]*)%% of max health%. the shell breaks when it cannot absorb any more damage%.$","수정은 가격당할 시 반응해, 피해 및 치유 효과를 흡수하는 보호막으로 공격자를 감쌉니다. 보호막은 원래 최대 생명력의 \0311\031%에 해당하는 피해를 흡수할 수 있지만, 치유 효과를 흡수하면 그만큼이 피해 흡수량에 더해져 최대 생명력의 \0312\031%까지 피해를 흡수할 수 있게 됩니다. 피해를 더는 흡수할 수 없게 되면 보호막이 깨집니다.",{0,0},{1,2}},aura={"^reacts when struck, encasing the attacker in a shell that absorbs incoming damage and healing%. initially the shell can absorb up to ([%+%-]?%d[%d,.%+%-to –]*)%% of max health in damage, but healing absorbed by the shell is added to this total, up to a cap of ([%+%-]?%d[%d,.%+%-to –]*)%% of max health%. the shell breaks when it cannot absorb any more damage%.$","가격당할 시 반응해, 피해 및 치유 효과를 흡수하는 보호막으로 공격자 보호\010보호막은 최대 생명력의 \0311\031%에 해당하는 피해 흡수\010치유 효과 흡수 시 그만큼이 피해 흡수량에 더해져, 최대 생명력의 \0312\031%까지 피해 흡수 가능\010피해를 더는 흡수할 수 없게 되면 보호막이 깨짐",{0,0},{1,2}}}
