rows[138296]={title={{15,1685034794},"령 폭발"},description={"^a catastrophic eruption of corrupted life energy deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all nearby players%.$","타락한 생명 에너지의 대재앙적인 폭발이 일어나 주위의 모든 아군에게 \0311\031의 암흑 피해를 입힙니다.",{0},{1}}}
rows[138297]={title={{13,1926830824},"불안정한 생령"},description={"^charges the target with storm energy, causing a surge of lightning every ([%+%-]?%d[%d,.%+%-to –]*) sec, which transfers unstable vita to the farthest available target%. the streaking lightning deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all players in its path, and afflicts those it touches with vita sensitivity%.$","대상을 폭풍 에너지로 충전시켜 \0311\031초마다 번개의 쇄도를 일으키게 합니다. 번개는 불안정한 생령을 가장 멀리 있는 가능한 대상에게 전달합니다. 번개 줄기는 날아가며 경로에 있는 모든 플레이어에게 \0312\031의 자연 피해를 입히고 민감한 생령 효과를 남깁니다.",{0,0},{1,2}},aura={{84,1218965151},"순수한 생령으로 충전됨\010만료시 불안정한 생령 효과가 가장 멀리 있는 플레이어에게 넘어감"}}
