rows[138300]={title={{19,1628731525},"소의 인내"},description={"^temporarily grants all players ([%+%-]?%d[%d,.%+%-to –]*)%% additional maximum health%. after the effect expires, the health is lost%. this effect lasts ([%+%-]?%d[%d,.]* %a+)%.$","일시적으로 모든 플레이어의 최대 생명력을 \0311\031%만큼 증가시킵니다. 얻은 생명력은 효과가 만료되면 사라집니다.\010\010\0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^health increased by ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum%.$","최대 생명력 \0311\031%만큼 증가",{0},{1}}}
