rows[138333]={title={{16,1268846689},"살의의 일격"},description={"^an unerringly accurate strike that turns the life force of the target against them, inflicting shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. the damage dealt is equal to the health of the target at the time of the attack%. this damage ignores most damage%-reducing effects%.$","한치의 어긋남도 없는 정교한 일격으로 대상이 가진 생명의 힘이 대상을 공격하게 하여 \0312\031 동안 \0311\031초마다 암흑 피해를 입힙니다. 이때 입히는 피해는 공격할 당시 대상의 생명력과 같습니다. 이 피해는 대부분의 피해 감소 효과를 무시합니다.",{0,1},{1,2}},aura={"^suffering ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 암흑 피해",{0,0},{1,2}}}
