rows[138605]={title={{10,1747290244},"검은 구멍"},aura={"^a nearby black hole is tearing you apart with shadowy energy, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec, and pulling you in%.$","근처에 검은 구멍\010암흑의 에너지에 의해 \0312\031초마다 \0311\031의 암흑 피해\010검은 구멍으로 끌려감",{0,0},{1,2}}}
rows[138606]={title={{18,775410532},"선리버의 지혜"},description={"^chance to shoot a fireball on attack, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage%.$","공격을 받으면 일정 확률로 화염구가 발사되어 \0311\031의 화염 피해를 입힙니다.",{0},{1}},aura={"^chance to shoot a fireball on attack, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage%.$","공격받을 시 일정 확률로 화염구를 발사해 \0311\031의 화염 피해",{0},{1}}}
rows[138607]={title={{11,1692381400},"불꽃 불러내기"},description={"^calls upon flames to destroy an enemy, inflicting ([%+%-]?%d[%d,.%+%-to –]*) fire damage and granting the caster 1 stack of fiery core%.$","불꽃을 불러내어 적을 공격합니다. \0311\031의 화염 피해를 입히고 시전자에게 1중첩의 불꽃의 정수 효과를 부여합니다.",{0},{1}}}
rows[138609]={title={{11,2124250503},"물질 바꾸기"},description={{279,1676696488},"대상 적을 구성하는 물질을 재배열합니다. 이 효과가 제거되면 대상은 자신과 가장 멀리 있는 아군과 자리를 바꾸며, 자신의 생명력과 같은 양의 피해를 해당 아군과 나누어 받습니다. 총 피해량 중 대상의 아군이 받는 피해의 비율은 1초마다 증가합니다."},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% of your maximum health to you and ([%+%-]?%d[%d,.%+%-to –]*)%% to your most distant ally when removed%. in addition, you swap places%.$","효과 제거 시 다음 효과 발생\010최대 생명력의 \0311\031%만큼 피해\010가장 멀리 있는 아군에게 최대 생명력의 \0312\031%만큼 피해\010해당 아군과 자리 바꿈",{0,0},{1,2}}}
