rows[138630]={title={{14,334527882},"별의 방어"},description={{144,1543596635},"생명력이 위험한 지경에 이르면, 강력한 방어 기제가 활성화됩니다. 이 효과는 180초마다 최대 1번씩만 발동합니다."},aura={"^taking ([%+%-]?%d[%d,.%+%-to –]*)%% reduced damage%. healing for ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health every ([%+%-]?%d[%d,.%+%-to –]*) secs%.$","받는 피해 \0311\031%만큼 감소\010\0313\031초마다 최대 생명력의 \0312\031% 회복",{0,0,0},{1,2,3}}}
