rows[139773]={title={{27,360484133},"사마귀 제국의 깃발"},description={{205,1331743904},"모구는 강력한 마법을 마음대로 쓸 수 있었지만, 거대한 기념물을 지을 때는 노예 동원을 선호했습니다. 이 장부에는 거대한 기념물 하나를 짓는 동안 들인 비용과 노예의 수가 상세히 적혀 있습니다."}}
