rows[139776]={title={{27,360484133},"사마귀 제국의 깃발"},description={{205,149235994},"사마귀들도 이런 물건을 만들 때 바람양모와 황제의 비단을 사용하긴 하지만, 더 선호하는 재료는 사마귀 종족 자신을 포함한 다양한 곤충형 생명체의 날개에서 얻은 일종의 \"섬유\"입니다. 이 깃발이 그 예입니다."}}
rows[139777]={title={{11,177928086},"돌 강타"},description={{103,873210151},"전방에 있는 모든 적의 머리를 강하게 내리쳐 물리 피해를 입히고 기절시킵니다."},aura={{8,318235535},"기절함"}}
rows[139778]={title={{23,2088613836},"얼어붙은 석상 격돌 준비"}}
rows[139779]={title={{18,1135199919},"고대 수액 먹이통"},description={{198,119590536},"사마귀는 키파리 수액을 충분히 숙성시킨 후 먹는 것을 좋아해, 수액을 숙성시키기 위해 이런 장치를 사용했습니다. 이 고대의 먹이통을 보면 세월이 흘러도 먹이통의 모양은 변하지 않았음을 알 수 있습니다."}}
rows[139780]={title={{18,468769207},"기도하는 사마귀"},description={{201,1212739293},"이 클락시바 조각상의 제작 시기는 티탄이 아제로스에 도착하던 때까지 거슬러 올라갑니다. 조각상 아래에 새겨진 글귀는 \"일곱 머리를 가진 자\"에게 바치는 기도입니다. \"클락시\"라는 단어는 고대에 \"사제\"를 뜻했습니다."}}
rows[139781]={title={{18,1703090203},"반응하지 않는 음향 신호기"},description={{215,1913646488},"사마귀의 음향 신호기에 숨겨진 기술은 다른 종족들로서는 이해할 수가 없습니다. 아마도 사마귀의 생물학적 특성에 의존하는 기술인 듯합니다. 이 고대의 신호기는 온전한 상태이지만, 신호기와 상호작용할 사마귀 없이는 완전히 무용지물입니다."}}
rows[139782]={title={{20,1071258851},"용장의 유해"},description={{201,280347370},"호박석 안에 용장을 보존하는 방식도 완전히 안전하지는 않은가 봅니다. 이 용장은 머리만 남아 있습니다. 정확히 언제부터 호박석 안에 보존되었는지는 알 수 없지만, 아마도 판다렌 혁명이 일어나기도 전이리라 추측됩니다."}}
rows[139783]={title={{11,1784474329},"사마귀 등불"},description={{116,1673050419},"이 등불에서 나오는 불빛은 불에 의한 것도, 마법에 의한 것도 아닙니다. 안쪽을 들여다보면 빛을 내는 곤충 여러 마리가 호박 안에 보존되어 있는 것을 볼 수 있습니다."}}
rows[139784]={title={{16,682894279},"꽃가루 채집기"},description={{106,1037700470},"이 물건의 용도가 무엇인지 정확히 파악할 순 없지만, 아마도 일종의 꽃가루 채집기인 듯합니다."}}
rows[139785]={title={{20,1277742820},"키파리 수액 용기"},description={{150,687555089},"이 용기는 호박으로 채색되어 있긴 하지만, 주 재료는 쿤총의 분비물입니다. 사마귀의 일상 용품은 대부분 이렇게 만들어졌습니다."}}
rows[139786]={title={{17,785766362},"사마귀 하늘 절단기"},description={{413,410759699},"이 고대의 \"하늘 절단기\" 칼은 사마귀 공중 부대가 이용할 목적으로 만들어졌습니다. 극도로 가볍고 균형이 잘 잡혀 있으며, 하늘에서 급강하해 폭탄을 떨어뜨리는 병사가 크게 호를 그리며 휘두를 수 있게 되어 있습니다. 대부분의 사마귀는 자라나서 강해지면 일종의 통과 의례로 날개를 잘라 버리고 무거운 갑옷과 무기를 사용하기 때문에, 사마귀의 가벼운 칼 중 이런 훌륭한 물건을 발견하는 것은 드문 일입니다. 이 칼은 용장이 사용하던 것으로 보입니다."}}
rows[139787]={title={{21,2053686668},"음파 생성기"},description={{374,834520613},"사마귀는 다른 필멸의 종족보다 훨씬 넓은 영역의 소리를 내고, 들을 수 있습니다. 극도로 높거나 낮은 주파수대의 소리에 대한 선천적인 이해를 바탕으로, 사마귀는 이런 무기를 만들어냈습니다. 이 장치에서 나오는 음파는 실제로 근육과 내장을 세포 수준으로 잘게 찢어버릴 수 있습니다. 음파에 직접 맞는 경우 내장이 녹아버릴 것입니다."}}
