rows[143007]={title={{15,856784983},"타락의 발차기"},description={"^spins rapidly in a circle, rooting himself and inflicting ([%+%-]?%d[%d,.%+%-to –]*) physical damage to targets within ([%+%-]?%d[%d,.%+%-to –]*) yards every second for ([%+%-]?%d[%d,.]* %a+)%. additionally torments targets struck, inflicting ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every two seconds for ([%+%-]?%d[%d,.]* %a+)%.$","제자리에 몸을 고정한 채 빠른 속도로 원을 그리며 회전합니다. \0312\031미터 내의 모든 적에게 \0313\031 동안 1초마다 \0311\031의 물리 피해를 입힙니다. 추가로 주변의 적에게 고통을 가하여 \0315\031 동안 1초마다 \0314\031의 암흑 피해를 입힙니다.",{0,0,1,0,1},{1,2,3,4,5}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) physical damage every second%.$","1초마다 \0311\031의 물리 피해",{0},{1}}}
