rows[143019]={title={{14,933234490},"타락의 맥주"},description={"^hurls a keg of corrupted brew at a distant target, inflicting ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards and slowing targets hit by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","먼 거리의 대상에 타락의 맥주가 든 통을 던져 반경 \0312\031미터 내에 있는 적에게 \0311\031의 암흑 피해를 입힙니다. 타락의 맥주에 적중한 대상은 \0314\031 동안 이동 속도가 \0313\031%만큼 감소합니다.",{0,0,0,1},{1,2,3,4}},aura={"^movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[143020]={title={{5,1908889661},"분열"},description={{233,1321690390},"잿빛너울에게서 샤 웅덩이와 오염된 웅덩이가 분출되도록 만들어, 방 한가운데에서 다시 모양을 갖추게 합니다. 분출된 샤 웅덩이를 없애고 오염된 웅덩이의 생명력이 완전히 회복될 때마다 잿빛너울의 에너지가 1만큼 감소합니다."},aura={{233,1321690390},"잿빛너울에게서 샤 웅덩이와 오염된 웅덩이가 분출하게 만든 뒤, 방 한가운데에서 다시 모양을 갖추도록 함. 방출된 샤 웅덩이를 없애고 오염된 웅덩이의 생명력이 완전히 회복될 때마다 잿빛너울의 에너지가 1만큼 감소"}}
