rows[143484]={title={{11,243711697},"진정"},description={"^general nazgrim needs to cool down after using a rage%-dependent ability, and is unable to use additional abilities that cost rage for ([%+%-]?%d[%d,.]* %a+)%.$","분노를 소모하는 능력을 사용한 후, 장군 나즈그림은 \0311\031 동안 진정 상태가 되어 분노를 소모하는 능력을 추가로 사용하지 못합니다.",{1},{1}},aura={{39,1201705259},"분노를 소모하는 능력을 사용할 수 없음"}}
