rows[143491]={title={{8,1997814722},"재앙"},description={"^calls forth a great calamity, striking all players for ([%+%-]?%d[%d,.%+%-to –]*)%% of their maximum health as shadow damage%. this also removes shadow word: bane from all targets%.$","엄청난 재앙을 불러와 모든 플레이어에게 최대 생명력의 \0311\031%에 해당하는 암흑 피해를 입힙니다. 이 효과는 모든 대상에서 어둠의 권능: 파멸 효과를 제거합니다.",{0},{1}}}
