rows[143494]={title={{14,851798207},"파열의 일격"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) physical damage and sunders the target's armor, reducing armor by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. generates ([%+%-]?%d[%d,.%+%-to –]*) rage per stack of sundering blow on the target%.$","\0311\031의 물리 피해를 입히고 대상의 방어구를 파열시켜 \0313\031 동안 방어도를 \0312\031%만큼 감소시킵니다. 대상에 파열의 일격이 중복될 때마다 \0314\031의 분노를 생성합니다.",{0,0,1,0},{1,2,3,4}},aura={"^armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","방어도 \0311\031%만큼 감소",{0},{1}}}
